python
def rosterProofBossReceipt(readings, k):
    a=readings
    out=[]
    n=len(a)
    def count(row,used):
        if row==n: return 1
        ways=0
        for c in range(n):
            if (a[row] & (1<<c)) and not (used & (1<<c)): ways+=count(row+1,used | (1<<c))
        return ways
    for c in range(n): out.append(count(1,1<<c) if a[0] & (1<<c) else 0)
    return sum((i+1)*x for i,x in enumerate(out))


java
class Solution {
  public int rosterProofBossReceipt(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int n=a.length;class Walk {int count(int row,int used){if(row==n)return 1;int ways=0;for(int c=0;c<n;c++)if((a[row]&(1<<c))!=0&&(used&(1<<c))==0)ways+=count(row+1,used|(1<<c));return ways;}}Walk w=new Walk();for(int c=0;c<n;c++)out.add((a[0]&(1<<c))!=0?w.count(1,1<<c):0);}
    int answer=0;for(int i=0;i<out.size();i++)answer+=(i+1)*out.get(i);return answer;
  }
}
